cd /app/tests; python - <<'EOF'
import re
def rw(p,f):
    s=open(p).read(); s=f(s); open(p,'w').write(s)
def h(s):
    a=s.index("class SettingsCase"); 
    return s[:a]+'''class SettingsCase(unittest.TestCase):
    """Gives every test its own settings, `self.conf`, with caching off, so
    that results from one test are never reused by another."""

    def setUp(self) -> None:
        self.conf = settings.make(cache_enabled=False)

    def use(self, **values) -> None:
        """Replace self.conf by settings with these values changed."""
        self.conf = dataclasses.replace(self.conf, **{k: settings.parse_value(k, v) for k, v in values.items()})
'''
rw('helpers.py',lambda s:h(s).replace("import os\n","import dataclasses\nimport os\n"))
def common(s):
    s=s.replace("settings.configure(","self.use(")
    for fn in ("run_batch","quote_all","cheapest","make_request"):
        s=re.sub(r"(?<![\w.])%s\("%fn, fn+"(self.conf, ",s)
    s=s.replace("render_quotes(","render_quotes(self.conf, ").replace("render_batch(","render_batch(self.conf, ")
    s=s.replace("zones.zone_for(","zones.zone_for(self.conf, ").replace("zones.zones_from(","zones.zones_from(self.conf, ").replace("registry.enabled(","registry.enabled(self.conf")
    s=s.replace("enabled(self.conf)","enabled(self.conf)")
    return s
for p in ("test_batch.py","test_output.py","test_quotes.py","test_zones.py"):
    rw(p,common)
EOF
grep -n "def \|make_request(self" test_quotes.py | sed -n 1,12p; sed -n 20,30p test_quotes.py; grep -n "enabled" test_zones.py; sed -n 66,102p test_settings.py
